                {"id": "q2", "topic": "Incident response", "question": "You see a suspicious sign-in on a work account. What should you do?", "options": [{"id": "a", "text": "Report it through the organization's incident process and preserve details"}, {"id": "b", "text": "Delete the audit record"}, {"id": "c", "text": "Try to break into the source address"}], "correct_option": "a", "explanation": "Prompt reporting and factual evidence let authorized responders investigate and contain the event safely."},
